#include <string>

class Solution {
public:
    std::string modifyString(std::string s) {
        int n = s.size();
        for (int i = 0; i < n; ++i) {
            if (s[i] == '?') {
                for (char ch : {'a', 'b', 'c'}) {
                    char prevCh = (i > 0 ? s[i - 1] : ' ');
                    char nextCh = (i + 1 < n ? s[i + 1] : ' ');
                    if (ch != prevCh && ch != nextCh) {
                        s[i] = ch;
                        break;
                    }
                }
            }
        }
        return s;
    }
};

class Solution {
    public String modifyString(String s) {
        char[] res = s.toCharArray();
        int n = res.length;
        for (int i = 0; i < n; i++) {
            if (res[i] == '?') {
                for (char ch = 'a'; ch <= 'c'; ch++) {
                    char prevCh = (i > 0 ? res[i - 1] : ' ');
                    char nextCh = (i + 1 < n ? res[i + 1] : ' ');
                    if (ch != prevCh && ch != nextCh) {
                        res[i] = ch;
                        break;
                    }
                }
            }
        }
        return new String(res);
    }
}

var modifyString = function(s) {
    const res = s.split("");
    const n = res.length;
    for (let i = 0; i < n; i++) {
        if (res[i] === "?") {
            for (const ch of ["a", "b", "c"]) {
                const prevCh = i > 0 ? res[i - 1] : "";
                const nextCh = i + 1 < n ? res[i + 1] : "";
                if (ch !== prevCh && ch !== nextCh) {
                    res[i] = ch;
                    break;
                }
            }
        }
    }
    return res.join("");
};
